def f(N: int, M: int, L: int, values: List[Tuple[int, int, int]]):
    def calculate_score(value_list):
        score = 0
        for i in range(len(value_list)):
            P_i, T_i, V_i = value_list[i]
            score += P_i * V_i if T_i == 0 else P_i * (V_i / (1 + T_i / 100))
        return score

    best_score = 0
